import { Object3D, Mesh, PlaneGeometry, Texture } from 'three/webgpu';
import { MeshBasicNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';
import '@/primitives';
import '@/text';

/**
 * @param {any} config
 * @param {any} ctx
 * @returns {Object3D}
 */
export default function createNode(config, ctx) {
    // Root container
    const root = new Object3D();
    const pos = config.position ?? { x: 0, y: 0, z: 0 };
    const rot = config.rotation ?? { x: 0, y: 0, z: 0 };
    const scl = config.scale ?? { x: 1, y: 1, z: 1 };

    root.position.set(pos.x, pos.y, pos.z);
    root.rotation.set(rot.x, rot.y, rot.z);
    root.scale.set(scl.x, scl.y, scl.z);

    // ---- Textured Plane -------------------------------------------------
    const planeGeometry = new PlaneGeometry(1, 1);
    /** @type {Texture} */
    const planeTexture = ctx.textureLoader.load(config.imageUrl);
    const planeMaterial = new MeshBasicNodeMaterial({
        map: planeTexture,
        transparent: true,
        depthTest: true,
        depthWrite: true
    });

    const planeMesh = new Mesh(planeGeometry, planeMaterial);
    planeMesh.position.set(0, 0, 0);
    root.add(planeMesh);

    // ---- Text Content ---------------------------------------------------
    if (config.textContent) {
        // Assume ctx.fontAtlas provides a method `createText` that returns an Object3D
        const textNode = ctx.fontAtlas.createText({
            string: config.textContent,
            // minimal styling – color can be taken from the palette
            color: config.palette?.ink ?? '#16161d',
            // size in scene units; using the provided typographic scale (headline ≈ 0.34)
            size: 0.34,
            // alignment centered on the plane
            hAlign: 'center',
            vAlign: 'middle'
        });
        // lift slightly to avoid Z‑fighting
        textNode.position.set(0, 0, 0.001);
        root.add(textNode);
    }

    // ---- Cinematic Primitives -------------------------------------------
    if (Array.isArray(config.cinematicPrimitives)) {
        config.cinematicPrimitives.forEach(p => {
            const primitiveFn = ctx.primitives[p.name];
            if (typeof primitiveFn === 'function') {
                primitiveFn(root, p.params);
            }
        });
    }

    // ---- Event Handlers -------------------------------------------------
    root.userData.handlers = {};

    // ---- Cleanup ---------------------------------------------------------
    root.userData.cleanup = () => {
        // Dispose geometry & material of the plane
        planeGeometry.dispose();
        planeMaterial.dispose();
        if (planeTexture) planeTexture.dispose();

        // Dispose any child meshes (e.g., text)
        root.traverse(child => {
            if (child.isMesh) {
                if (child.geometry) child.geometry.dispose();
                if (child.material) {
                    if (Array.isArray(child.material)) {
                        child.material.forEach(m => m.dispose && m.dispose());
                    } else if (child.material.dispose) {
                        child.material.dispose();
                    }
                }
            }
        });

        // Kill all GSAP timelines that might have been created elsewhere
        gsap.globalTimeline.clear();
    };

    return root;
}
